(() => {
    const COMMAND_PREFIX = "--|-";
    const LICENSE_STORAGE_KEY = "__hdmLicenseKey";
    const DEVICE_HASH_STORAGE_KEY = "__hdmDeviceHash";
    const LICENSE_SESSION_STORAGE_KEY = "__hdmLicenseSession";
    const CONFIG = {"apiBase":"http://23.160.168.166:4008","licenseKey":"KETTU-1FDF0A-62C655-0C456E-70C98E","bundleId":"hdm","installId":"install-7a32f9f2e9323dcf","keyFragment":"1FDF0A62C655","headerName":"X-HDM-Install-Key","headerValue":"JwyxpXt80sbHNZoLSJHvgdFvDpXb-ll7","runtimeKeyBase64":"2+0gc5MUUNmK/ke9fJH9nOMynp5x+cl411GMtRhasHg=","embeddedRuntimePayload":{"algorithm":"XORSHIFT128","iv":"vLgGkS+LqhIOyKLC9MoN2w==","ciphertext":""},"runtimeLeaseHeaderName":"X-HDM-Runtime-Lease","runtimeLeaseRenewIntervalMs":2000};
    const state = {
        logger: null,
        remotePlugin: null,
        storage: null,
        utilityPatches: [],
        messageActions: null,
        pluginActionScheduled: false,
        crashHandlerInstalled: false,
        lastCrashSignature: null,
        lastCrashAt: 0,
        pendingRemoteLogs: [],
        logFlushTimer: null,
        logFlushInFlight: false,
        bootstrapInFlight: false,
        unloaded: false,
    };

    function initLogger() {
        try {
            state.logger = vendetta?.logger || console;
        } catch {
            state.logger = console;
        }
    }

    function log(message, details) {
        if (!state.logger) {
            initLogger();
        }
        
        try {
            if (details === undefined) {
                state.logger.log(`[HDM Installer] ${message}`);
            } else {
                state.logger.log(`[HDM Installer] ${message}`, details);
            }
        } catch {
            // Silently fail if logging breaks
        }

        try {
            enqueueLoaderEvent(
                details instanceof Error ? "error" : "info",
                "log",
                String(message || ""),
                details,
            );
        } catch {
            // Ignore remote queue failures.
        }
    }

    function showToast(message) {
        try {
            vendetta.ui?.toasts?.showToast?.(message);
        } catch (error) {
            log(message, error);
        }
    }

    function createTaggedError(message, code) {
        const error = new Error(message);
        error.code = code;
        return error;
    }

    function isServerUnreachableError(error) {
        const code = String(error?.code || "");
        const message = String(error?.message || "").toLowerCase();
        return code === "server_unreachable"
            || code === "server_timeout"
            || message.includes("timed out")
            || message.includes("network request failed")
            || message.includes("failed to fetch")
            || message.includes("networkerror")
            || message.includes("load failed");
    }

    function isLicenseInvalidError(error) {
        const code = String(error?.code || "");
        if ([
            "license_invalid",
            "invalid_key",
            "not_found",
            "revoked",
            "expired",
            "device_mismatch",
            "device_required",
            "invalid_device_hash",
            "product_mismatch",
            "loader_expired",
            "runtime_lease_invalid",
            "install_invalid",
        ].includes(code)) {
            return true;
        }

        const message = String(error?.message || "").toLowerCase();
        return message.includes("license")
            || message.includes("session")
            || message.includes("device hash")
            || message.includes("runtime lease")
            || message.includes("install id");
    }

    function getCurrentPluginId() {
        try {
            const pluginId = vendetta?.plugin?.id;
            return typeof pluginId === "string" && pluginId.trim().length > 0 ? pluginId : undefined;
        } catch {
            return undefined;
        }
    }

    function getPluginManager() {
        try {
            return vendetta?.plugins
                || globalThis.vendetta?.plugins
                || globalThis.window?.vendetta?.plugins;
        } catch {
            return null;
        }
    }

    function schedulePluginAction(mode, reason) {
        if (state.pluginActionScheduled) {
            return;
        }

        state.pluginActionScheduled = true;
        const actionLabel = mode === "remove" ? "Removing" : "Disabling";
        log(`${actionLabel} plugin: ${reason}`);
        showToast(reason);

        const pluginId = getCurrentPluginId();
        const pluginManager = getPluginManager();
        setTimeout(() => {
            try {
                if (mode === "remove" && pluginId && typeof pluginManager?.removePlugin === "function") {
                    void Promise.resolve(pluginManager.removePlugin(pluginId)).catch((error) => {
                        log("Automatic plugin removal failed", error);
                    });
                    return;
                }

                if (mode === "disable" && pluginId && typeof pluginManager?.stopPlugin === "function") {
                    pluginManager.stopPlugin(pluginId, true);
                    return;
                }

                log(`Automatic plugin ${mode} is unavailable in this Kettu build.`);
            } catch (error) {
                log(`Automatic plugin ${mode} failed`, error);
            }
        }, 150);
    }

    function removeCurrentPlugin(reason) {
        schedulePluginAction("remove", reason);
    }

    function disableCurrentPlugin(reason) {
        schedulePluginAction("disable", reason);
    }

    function handlePluginIssue(error, fallbackMessage) {
        if (isServerUnreachableError(error)) {
            disableCurrentPlugin(error?.message || "License server is unreachable. Disabling plugin.");
            return;
        }

        if (isLicenseInvalidError(error)) {
            removeCurrentPlugin(error?.message || "License key is invalid. Removing plugin.");
            return;
        }

        disableCurrentPlugin(error?.message || fallbackMessage);
    }

    function serializeLogDetails(details) {
        if (details == null) {
            return undefined;
        }

        if (typeof details === "string") {
            return details;
        }

        if (details instanceof Error) {
            return {
                name: details.name,
                message: details.message,
                code: details.code,
                stack: details.stack,
            };
        }

        try {
            return JSON.parse(JSON.stringify(details));
        } catch {
            return String(details);
        }
    }

    function getErrorMessage(error, fallback = "Unknown loader error.") {
        if (typeof error?.message === "string" && error.message.trim()) {
            return error.message.trim();
        }

        if (typeof error === "string" && error.trim()) {
            return error.trim();
        }

        try {
            const normalized = String(error || "").trim();
            return normalized || fallback;
        } catch {
            return fallback;
        }
    }

    function shouldDeduplicateCrash(stage, error) {
        const details = serializeLogDetails(error);
        const signature = JSON.stringify({
            stage,
            message: getErrorMessage(error),
            stack: details?.stack || details?.message || details || "",
        });
        const now = Date.now();
        if (state.lastCrashSignature === signature && now - state.lastCrashAt < 5000) {
            return true;
        }

        state.lastCrashSignature = signature;
        state.lastCrashAt = now;
        return false;
    }

    function enqueueLoaderEvent(level, stage, message, details) {
        state.pendingRemoteLogs.push({
            level,
            stage,
            message: normalizeLogMessage(message),
            details: serializeLogDetails(details),
        });

        if (state.pendingRemoteLogs.length > 200) {
            state.pendingRemoteLogs.splice(0, state.pendingRemoteLogs.length - 200);
        }
    }

    function normalizeLogMessage(message) {
        try {
            const normalized = String(message || "").trim();
            return normalized || "Loader event";
        } catch {
            return "Loader event";
        }
    }

    async function postLoaderLogEntry(entry) {
        const controller = typeof AbortController === "function" ? new AbortController() : null;
        const timeoutId = setTimeout(() => {
            try {
                controller?.abort?.();
            } catch {}
        }, 1500);

        try {
            const response = await fetch(`${CONFIG.apiBase}/api/install/log`, {
                method: "POST",
                cache: "no-store",
                headers: {
                    "Content-Type": "application/json",
                    [CONFIG.headerName]: CONFIG.headerValue,
                },
                body: JSON.stringify({
                    installId: CONFIG.installId,
                    licenseKey: CONFIG.licenseKey,
                    pluginId: getCurrentPluginId(),
                    level: entry.level,
                    stage: entry.stage,
                    message: entry.message,
                    details: entry.details,
                }),
                signal: controller?.signal,
            });

            if (!response?.ok) {
                let responseText = "";
                try {
                    responseText = await response.text();
                } catch {}

                const suffix = responseText ? ` ${responseText}` : "";
                throw new Error(`Install log upload failed (${response?.status || "unknown"}).${suffix}`);
            }
        } finally {
            clearTimeout(timeoutId);
        }
    }

    async function flushPendingLoaderEvents() {
        if (state.logFlushInFlight || state.pendingRemoteLogs.length === 0) {
            return;
        }

        state.logFlushInFlight = true;
        const batch = state.pendingRemoteLogs.splice(0, 25);

        try {
            for (const entry of batch) {
                await postLoaderLogEntry(entry);
            }
        } catch (error) {
            try {
                if (!state.logger) {
                    initLogger();
                }
                state.logger?.warn?.("[HDM Installer] Remote log flush failed", error);
            } catch {}

            state.pendingRemoteLogs.unshift(...batch);
            if (state.pendingRemoteLogs.length > 200) {
                state.pendingRemoteLogs.splice(200);
            }
        } finally {
            state.logFlushInFlight = false;
        }
    }

    function startLogFlushLoop() {
        if (state.logFlushTimer) {
            clearInterval(state.logFlushTimer);
        }

        state.logFlushTimer = setInterval(() => {
            void flushPendingLoaderEvents();
        }, 5000);
    }

    async function reportLoaderEvent(level, stage, message, details) {
        enqueueLoaderEvent(level, stage, message, details);
        await flushPendingLoaderEvents();
    }

    function reportCrash(stage, error, details) {
        if (shouldDeduplicateCrash(stage, error)) {
            return;
        }

        void reportLoaderEvent(
            "error",
            stage,
            getErrorMessage(error, "Unhandled loader crash."),
            details ?? error,
        );
    }

    function attachCrashListener(target, eventName, handler) {
        if (!target || typeof target.addEventListener !== "function" || typeof target.removeEventListener !== "function") {
            return;
        }

        try {
            target.addEventListener(eventName, handler);
            state.utilityPatches.push(() => {
                try {
                    target.removeEventListener(eventName, handler);
                } catch {}
            });
        } catch {}
    }

    function installCrashReporting() {
        if (state.crashHandlerInstalled) {
            return;
        }

        state.crashHandlerInstalled = true;

        const handleUnhandledRejection = (event) => {
            const reason = event?.reason ?? event;
            reportCrash("unhandledrejection", reason, {
                reason: serializeLogDetails(reason),
            });
            handlePluginIssue(reason, "Unhandled promise rejection. Disabling plugin.");
        };

        const handleGlobalErrorEvent = (event) => {
            const error = event?.error || createTaggedError(
                event?.message || "Unhandled runtime error.",
                "runtime_crash",
            );
            reportCrash("error", error, {
                filename: event?.filename,
                line: event?.lineno,
                column: event?.colno,
                error: serializeLogDetails(error),
            });
            handlePluginIssue(error, "Runtime error detected. Disabling plugin.");
        };

        attachCrashListener(globalThis, "unhandledrejection", handleUnhandledRejection);
        attachCrashListener(globalThis, "error", handleGlobalErrorEvent);
        attachCrashListener(globalThis.window, "unhandledrejection", handleUnhandledRejection);
        attachCrashListener(globalThis.window, "error", handleGlobalErrorEvent);

        try {
            const errorUtils = globalThis.ErrorUtils;
            if (errorUtils && typeof errorUtils.getGlobalHandler === "function" && typeof errorUtils.setGlobalHandler === "function") {
                const previousHandler = errorUtils.getGlobalHandler();
                const wrappedHandler = (error, isFatal) => {
                    reportCrash(isFatal ? "fatal" : "errorutils", error, {
                        isFatal: Boolean(isFatal),
                        error: serializeLogDetails(error),
                    });
                    handlePluginIssue(
                        error,
                        isFatal
                            ? "Fatal runtime error detected. Disabling plugin."
                            : "Runtime error detected. Disabling plugin.",
                    );

                    try {
                        if (typeof previousHandler === "function") {
                            previousHandler(error, isFatal);
                        }
                    } catch {}
                };

                errorUtils.setGlobalHandler(wrappedHandler);
                state.utilityPatches.push(() => {
                    try {
                        errorUtils.setGlobalHandler(previousHandler);
                    } catch {}
                });
            }
        } catch (error) {
            log("Failed to install crash reporting hooks", error);
        }
    }

    function getPluginStorage() {
        if (!state.storage) {
            try {
                state.storage = vendetta?.plugin?.storage || {};
            } catch {
                state.storage = {};
            }
        }

        return state.storage;
    }

    function coerceString(value) {
        if (typeof value === "string") {
            const trimmed = value.trim();
            return trimmed.length > 0 ? trimmed : undefined;
        }

        if (value == null) {
            return undefined;
        }

        const normalized = String(value).trim();
        return normalized.length > 0 ? normalized : undefined;
    }

    function createDeviceHash() {
        const randomUuid = globalThis.crypto?.randomUUID?.();
        if (typeof randomUuid === "string" && randomUuid.length > 0) {
            return `hdm-${randomUuid}`;
        }

        return `hdm-${Math.random().toString(36).slice(2)}-${Date.now().toString(36)}`;
    }

    function getOrCreateDeviceHash() {
        const storage = getPluginStorage();
        const existing = coerceString(storage[DEVICE_HASH_STORAGE_KEY]);

        if (existing) {
            return existing;
        }

        const next = createDeviceHash();
        storage[DEVICE_HASH_STORAGE_KEY] = next;
        return next;
    }

    function persistEmbeddedLicenseKey() {
        const storage = getPluginStorage();
        storage[LICENSE_STORAGE_KEY] = CONFIG.licenseKey;
    }

    function persistLicenseSession(payload, deviceHash) {
        const storage = getPluginStorage();
        storage[LICENSE_SESSION_STORAGE_KEY] = JSON.stringify({
            licenseKey: CONFIG.licenseKey,
            deviceHash,
            sessionToken: payload.sessionToken,
            sessionExpiresAt: payload.sessionExpiresAt,
            overlayStateUrl: payload.overlayStateUrl,
            runtimeLeaseToken: payload.runtimeLeaseToken,
            runtimeLeaseExpiresAt: payload.runtimeLeaseExpiresAt,
            runtimeLeaseHeaderName: payload.runtimeLeaseHeaderName || CONFIG.runtimeLeaseHeaderName,
            runtimeLeaseRenewIntervalMs: payload.runtimeLeaseRenewIntervalMs || CONFIG.runtimeLeaseRenewIntervalMs,
        });
    }

    function getLicenseStatusText() {
        const deviceHash = coerceString(getPluginStorage()[DEVICE_HASH_STORAGE_KEY]);
        const licenseSuffix = CONFIG.licenseKey.slice(-6);
        const deviceSuffix = deviceHash ? deviceHash.slice(-8) : "missing";
        return `Installer active (...${licenseSuffix}) on device (...${deviceSuffix}).`;
    }

    async function fetchJson(url, options = {}) {
        let response;
        try {
            response = await fetch(url, {
                cache: "no-store",
                ...options,
            });
        } catch (error) {
            throw createTaggedError(error?.message || "License server is unreachable.", "server_unreachable");
        }

        let payload = null;
        try {
            payload = await response.json();
        } catch (error) {
            log(`Failed to parse JSON from ${url}`, error);
        }

        return { response, payload };
    }

    function base64ToBytes(value) {
        const binary = globalThis.atob(value);
        const bytes = new Uint8Array(binary.length);
        for (let index = 0; index < binary.length; index += 1) {
            bytes[index] = binary.charCodeAt(index);
        }

        return bytes;
    }

    function readUint32LE(bytes, offset) {
        return (
            ((bytes[offset] || 0))
            | ((bytes[offset + 1] || 0) << 8)
            | ((bytes[offset + 2] || 0) << 16)
            | ((bytes[offset + 3] || 0) << 24)
        ) >>> 0;
    }

    function createXorShiftState(keyBytes, ivBytes) {
        const paddedIv = new Uint8Array(16);
        paddedIv.set(ivBytes.slice(0, 16));

        const state = new Uint32Array(4);
        state[0] = (readUint32LE(keyBytes, 0) ^ readUint32LE(paddedIv, 0) ^ 0x243f6a88) >>> 0;
        state[1] = (readUint32LE(keyBytes, 4) ^ readUint32LE(keyBytes, 16) ^ 0x85a308d3) >>> 0;
        state[2] = (readUint32LE(keyBytes, 8) ^ readUint32LE(paddedIv, 4) ^ 0x13198a2e) >>> 0;
        state[3] = (readUint32LE(keyBytes, 12) ^ readUint32LE(paddedIv, 8) ^ 0x03707344) >>> 0;

        if ((state[0] | state[1] | state[2] | state[3]) === 0) {
            state[0] = 0x6d2b79f5;
        }

        return state;
    }

    function nextXorShiftWord(state) {
        let t = state[3] >>> 0;
        const s = state[0] >>> 0;

        state[3] = state[2] >>> 0;
        state[2] = state[1] >>> 0;
        state[1] = s >>> 0;

        t ^= (t << 11) >>> 0;
        t ^= t >>> 8;

        const next = (t ^ s ^ (s >>> 19)) >>> 0;
        state[0] = next;
        return next;
    }

    function xorShiftCrypt(keyBytes, ivBytes, inputBytes) {
        const state = createXorShiftState(keyBytes, ivBytes);
        const output = new Uint8Array(inputBytes.length);
        let word = 0;
        let remaining = 0;

        for (let index = 0; index < inputBytes.length; index += 1) {
            if (remaining === 0) {
                word = nextXorShiftWord(state);
                remaining = 4;
            }

            output[index] = inputBytes[index] ^ (word & 0xff);
            word >>>= 8;
            remaining -= 1;
        }

        return output;
    }

    async function activateLicense() {
        persistEmbeddedLicenseKey();
        const deviceHash = getOrCreateDeviceHash();
        const { response, payload } = await fetchJson(`${CONFIG.apiBase}/api/licenses/activate`, {
            method: "POST",
            headers: {
                "Content-Type": "application/json",
            },
            body: JSON.stringify({
                licenseKey: CONFIG.licenseKey,
                deviceHash,
                plugin: "HDM",
                installId: CONFIG.installId,
            }),
        });

        if (!response.ok || !payload?.ok) {
            throw createTaggedError(
                payload?.reason || payload?.error || `License activation failed (${response.status}).`,
                payload?.code || "license_invalid"
            );
        }

        persistLicenseSession(payload, deviceHash);
        return payload;
    }

    async function decryptRuntimeBundle(payload) {
        if (!payload || typeof payload.ciphertext !== "string" || typeof payload.iv !== "string") {
            throw new Error("Encrypted runtime bundle payload was invalid.");
        }

        const keyBytes = base64ToBytes(CONFIG.runtimeKeyBase64);
        const ivBytes = base64ToBytes(payload.iv);
        const ciphertextBytes = base64ToBytes(payload.ciphertext);

        if (payload.algorithm === "XORSHIFT128") {
            const plaintext = xorShiftCrypt(keyBytes, ivBytes, ciphertextBytes);
            return new TextDecoder().decode(plaintext);
        }

        const cryptoApi = globalThis.crypto?.subtle;
        if (!cryptoApi) {
            throw new Error("No supported runtime decryption API is available.");
        }

        const runtimeKey = await cryptoApi.importKey(
            "raw",
            keyBytes,
            { name: "AES-GCM" },
            false,
            ["decrypt"]
        );

        const plaintext = await cryptoApi.decrypt(
            {
                name: "AES-GCM",
                iv: ivBytes,
            },
            runtimeKey,
            ciphertextBytes
        );

        return new TextDecoder().decode(new Uint8Array(plaintext));
    }

    async function loadRemotePlugin(session) {
        const payload = CONFIG.embeddedRuntimePayload;
        if (!payload || typeof payload !== "object") {
            throw createTaggedError("Embedded runtime bundle payload was missing.", "runtime_bundle_unavailable");
        }

        log("Decrypting runtime bundle...");
        const source = await decryptRuntimeBundle(payload);
        
        log("Setting up global session...");
        globalThis.__HDM_PLUGIN_STORAGE = getPluginStorage();
        globalThis.__HDM_LICENSE_API_BASE = CONFIG.apiBase;
        globalThis.__HDM_PREMIUM_SESSION = {
            ...session,
            bundleId: CONFIG.bundleId,
            bundleUrl: `${CONFIG.apiBase}/key/${encodeURIComponent(CONFIG.licenseKey)}/${encodeURIComponent(CONFIG.keyFragment)}/index.js`,
            trustedManifestUrl: `${CONFIG.apiBase}/api/trusted-bundles/${encodeURIComponent(CONFIG.bundleId)}/manifest`,
            overlayStateUrl: session.overlayStateUrl,
            runtimeLeaseToken: session.runtimeLeaseToken,
            runtimeLeaseExpiresAt: session.runtimeLeaseExpiresAt,
            runtimeLeaseHeaderName: session.runtimeLeaseHeaderName || CONFIG.runtimeLeaseHeaderName,
            runtimeLeaseRenewIntervalMs: session.runtimeLeaseRenewIntervalMs || CONFIG.runtimeLeaseRenewIntervalMs,
        };

        log("Evaluating runtime bundle...");
        let raw;
        try {
            raw = eval(source);
        } catch (error) {
            throw new Error(`Runtime bundle parse failed: ${error?.message || error}`);
        }

        log("Initializing plugin object...");
        const plugin = typeof raw === "function" ? raw() : raw;
        if (!plugin || typeof plugin !== "object") {
            throw new Error("Runtime bundle did not return a valid plugin object.");
        }

        log("Runtime bundle loaded successfully");
        return plugin;
    }

    function buildCommandUsage(name, args = "") {
        return `${COMMAND_PREFIX}${name}${args ? ` ${args}` : ""}`;
    }

    function handlePrefixCommand(rawContent) {
        const trimmed = rawContent.trim();
        if (!trimmed.startsWith(COMMAND_PREFIX)) return false;

        const [rawCommand] = trimmed.split(/\s+/, 1);
        const command = rawCommand.slice(COMMAND_PREFIX.length).toLowerCase();

        if (command === "licenseinfo") {
            showToast(getLicenseStatusText());
            return true;
        }

        if (command === "installinfo") {
            showToast(`Install ${CONFIG.installId} via ${buildCommandUsage("licenseinfo")}`);
            return true;
        }

        return false;
    }

    function installPrefixCommands() {
        try {
            const instead = vendetta?.patcher?.instead;
            if (!instead || !state.messageActions?.sendMessage) {
                log("Installer command patch could not be installed");
                return;
            }

            state.utilityPatches.push(instead("sendMessage", state.messageActions, (args, original) => {
                const [, message] = args;
                const content = message?.content;

                if (typeof content === "string" && handlePrefixCommand(content)) {
                    return;
                }

                return original.apply(state.messageActions, args);
            }));
        } catch (error) {
            log("Failed to install prefix commands", error);
        }
    }

    function cleanup() {
        for (const unpatch of state.utilityPatches.splice(0)) {
            try {
                unpatch();
            } catch (error) {
                log("Failed to remove installer patch", error);
            }
        }
    }

    async function bootstrapRemotePlugin() {
        if (state.bootstrapInFlight || state.unloaded) {
            return;
        }

        state.bootstrapInFlight = true;

        try {
            log("Starting installer bootstrap...");
            log("Activating license...");
            const session = await activateLicense();

            if (state.unloaded) {
                return;
            }

            log("Loading remote plugin...");
            const remotePlugin = await loadRemotePlugin(session);

            if (state.unloaded) {
                if (typeof remotePlugin?.onUnload === "function") {
                    try {
                        await remotePlugin.onUnload();
                    } catch (error) {
                        log("Remote plugin cleanup after unload failed", error);
                    }
                }
                return;
            }

            state.remotePlugin = remotePlugin;

            if (typeof remotePlugin.onLoad === "function") {
                log("Calling remote plugin onLoad...");
                await remotePlugin.onLoad();
            }

            log("Installer loaded runtime bundle");
        } catch (error) {
            log("Installer failed to load runtime bundle", error);
            await reportLoaderEvent(
                "error",
                "onLoad",
                error?.message || "Premium runtime failed to load.",
                error,
            );
            handlePluginIssue(error, "Premium runtime failed to load. Disabling plugin.");
        } finally {
            state.bootstrapInFlight = false;
        }
    }

    return {
        onLoad() {
            state.unloaded = false;
            log("Starting installer onLoad...");
            installCrashReporting();
            startLogFlushLoop();
            persistEmbeddedLicenseKey();

            try {
                state.messageActions = vendetta?.metro?.findByProps?.("sendMessage");
            } catch (error) {
                log("Failed to find message actions", error);
            }

            installPrefixCommands();
            setTimeout(() => {
                void bootstrapRemotePlugin();
            }, 0);
        },

        async onUnload() {
            state.unloaded = true;
            try {
                if (typeof state.remotePlugin?.onUnload === "function") {
                    await state.remotePlugin.onUnload();
                }
            } catch (error) {
                log("Runtime bundle failed to unload cleanly", error);
                void reportLoaderEvent(
                    "error",
                    "onUnload",
                    error?.message || "Runtime bundle failed to unload cleanly.",
                    error,
                );
            } finally {
                if (state.logFlushTimer) {
                    clearInterval(state.logFlushTimer);
                    state.logFlushTimer = null;
                }

                await flushPendingLoaderEvents();
                state.remotePlugin = null;
                state.pluginActionScheduled = false;
                delete globalThis.__HDM_PLUGIN_STORAGE;
                delete globalThis.__HDM_PREMIUM_SESSION;
                delete globalThis.__HDM_LICENSE_API_BASE;
                cleanup();
            }
        },
    };
})()
